public class ErrorVsExceptionDemonstration {
    // Simulates an application-level recoverable condition
    public static void processUserAge(String ageStr) {
        try {
            int age = Integer.parseInt(ageStr);
            System.out.println("Valid age processed: " + age);
        } catch (NumberFormatException e) {
            System.out.println("Recoverable Exception caught: Invalid age format '" + ageStr + "'");
        }
    }

    // Demonstrates StackOverflowError mechanics (educational demonstration)
    public static void causeStackOverflow(int depth) {
        if (depth > 50000) return; // Safeguard
        causeStackOverflow(depth + 1);
    }

    public static void main(String[] args) {
        System.out.println("--- 1. Handling Recoverable Exception ---");
        processUserAge("25");
        processUserAge("twenty-five"); // Throws and recovers from NumberFormatException

        System.out.println("\n--- 2. Inspecting Hierarchy ---");
        System.out.println("Is Exception a Throwable? " + (new Exception() instanceof Throwable));
        System.out.println("Is Error a Throwable? " + (new Error() instanceof Throwable));
    }
}

