practiceProblems.solutionCode:
public class RecoverableLoop {
    public static void main(String[] args) {
        String[] values = {"10", "twenty", "30"};
        int sum = 0;
        for (String v : values) {
            try {
                sum += Integer.parseInt(v);
            } catch (NumberFormatException e) {
                // Recover by treating invalid input as 0
            }
        }
        System.out.println("Total: " + sum);
    }
}

