practiceProblems.solutionCode:
public class BoundedRecursion {
    static int countFrames(int depth) {
        if (depth == 100) {
            return depth;
        }
        return countFrames(depth + 1);
    }
    public static void main(String[] args) {
        System.out.println("Max Depth reached: " + countFrames(1));
    }
}

